import {createCaseUI} from './case-ui.js';
import {PRIMARY_MODULES as MODULES,PRIMARY_LESSONS as LESSONS,PRIMARY_QUESTIONS as QUESTIONS,LESSONS as ALL_LESSONS,EXTRA_LESSONS,SOURCES,SCOPE} from './content.js';
import {freshState,validateState,dayKey,streakDays,completion,shuffle,byId,makeSession,submitAnswer,advance,hasAnswer,correctAnswer,mistakeQuestions,dueQuestions,examQuestions} from './engine.js';
const KEY='obliga.progress.v1',root=document.querySelector('#app');let saveError=false,state,view='learn',moduleId=1,lessonId='ob1',flashIndex=0,flashBack=false,pendingChange=null;
try{const raw=localStorage.getItem(KEY);state=raw?validateState(JSON.parse(raw)):freshState();}catch{state=freshState();saveError=true;}
if(state.session)view=state.session.finished?'result':'quiz';
if(new URLSearchParams(location.search).get('section')==='cases')view='cases';
const e=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={map:'M4 5l5-2 6 2 5-2v16l-5 2-6-2-5 2z M9 3v16 M15 5v16',review:'M3 10a9 9 0 1 1 2 9 M3 4v6h6',book:'M3 4h6c2 0 3 1 3 3v14c0-2-1-3-3-3H3z M21 4h-6c-2 0-3 1-3 3v14c0-2 1-3 3-3h6z',chart:'M4 20h16 M7 16v-5 M12 16V5 M17 16V9',bolt:'M13 2L5 14h7l-1 8 8-12h-7z',flame:'M12 2c2 6 7 7 7 12a7 7 0 0 1-14 0c0-3 1-5 3-7 0 3 2 4 3 5 2-3 2-6 1-10z',right:'M5 12h14 M13 6l6 6-6 6',left:'M19 12H5 M11 6l-6 6 6 6',check:'M5 12l4 4L19 6',scale:'M12 3v17 M6 21h12 M4 7h16 M6 7l-3 7h6z M18 7l-3 7h6z',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h4',handshake:'M2 9l5-4 5 2 5-2 5 4-4 9-5 3-6-3z M7 5l-2 9 M17 5l2 9 M8 11l4-3 4 4-3 3-3-2',arrows:'M3 7h17l-4-4 M21 17H4l4 4',key:'M9 13a5 5 0 1 1 4-4l8 8-3 3-2-2-2 2-3-3',shield:'M12 2l8 4v6c0 5-8 10-8 10s-8-5-8-10V6z M8 12l3 3 5-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',star:'M12 2l3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z'};
const icon=n=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[n]||paths.book}"/></svg></span>`;
const btn=(text,action,cls='primary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const caseUI=createCaseUI({getState:()=>state,save,go,refresh:()=>render(),e,btn,icon});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveError=false;}catch{saveError=true;toast('No se pudo guardar. Podés exportar tu progreso en Mi avance.');}}
function toast(text){document.querySelector('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.querySelector('#toast').textContent='',5000);}
const currentLesson=()=>ALL_LESSONS.find(l=>l.id===lessonId)||LESSONS[0];
const nextLesson=()=>LESSONS.find(l=>!(state.lessons[l.id]?.best>=80))||LESSONS[0];
const percent=m=>{const ls=LESSONS.filter(l=>l.module===m);return Math.round(ls.filter(l=>state.lessons[l.id]?.best>=80).length/ls.length*100);};
function nav(mobile=false){return `<nav class="${mobile?'bottomnav':'side-nav'}" aria-label="${mobile?'Navegación móvil':'Navegación principal'}">${[['learn','map','Mi camino'],['cases','file','Casos'],['review','review','Repasar'],['notes','book','Apuntes'],['progress','chart','Mi avance']].map(([id,ic,label])=>btn(`${icon(ic)}${label}`,`nav:${id}`,`nav-btn ${view===id||id==='cases'&&view==='case'||id==='learn'&&['module','lesson','quiz','result','exam'].includes(view)?'active':''}`,view===id?'aria-current="page"':'')).join('')}</nav>`;}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">o</span>obliga</div>${nav()}<div class="side-note"><b>UN TEMA A LA VEZ</b><br>Obligaciones y contratos<br>Primer parcial · 2026<br><button class="inline-link" data-action="nav:sources">Alcance y fuentes</button></div></aside><main class="main" id="main"><header class="topbar"><span class="crumb">Tu espacio de estudio / Primer parcial</span><div class="brand mobile-brand"><span class="brand-mark">o</span>obliga</div><div class="stats"><span class="stat" title="Días consecutivos de práctica">${icon('flame')}${streakDays(state)} <span class="small">${streakDays(state)===1?'día':'días'}</span></span><span class="stat" title="Experiencia acumulada">${icon('bolt')}${state.xp} XP</span><span class="avatar" aria-hidden="true">A</span></div></header>${saveError?'<p class="save-warning" role="status">No pudimos recuperar o guardar el progreso local. Podés seguir practicando y exportarlo desde Mi avance.</p>':''}${content}</main></div>${nav(true)}<dialog id="confirm-exit"><h2>¿Salir de esta práctica?</h2><p>Podés guardar la sesión para retomarla o descartarla. Las respuestas que ya diste quedan en tu progreso.</p><div class="action-row">${btn('Seguir','cancel-exit','secondary')}${btn('Guardar y salir','save-exit')}${btn('Descartar sesión','discard','ghost')}</div></dialog><dialog id="confirm-change"><h2 id="change-title"></h2><p id="change-description"></p><div class="action-row">${btn('Cancelar','cancel-change','secondary')}${btn('Confirmar','apply-change')}</div></dialog>`;}
function weekly(){return `<div class="week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return `<span class="day ${state.days[dayKey(d)]?'done':''}"><span>${['D','L','M','M','J','V','S'][d.getDay()]}</span><b>${state.days[dayKey(d)]?'✓':d.getDate()}</b></span>`;}).join('')}</div>`;}
function learn(){const next=nextLesson(),today=state.days[dayKey()]||0,completed=completion(state);return `<div class="intro"><p class="welcome">Volvé a conectar con lo que aprendés.</p><h1>Un tema a la vez.<br>Un poco más cerca.</h1><p class="muted">Tu camino de obligaciones y contratos hasta el primer parcial.</p></div><div class="case-entry"><div><b>Casos de la materia</b><p class="small muted">130 casos de los Word · 410 consignas + práctica extra</p></div>${btn('Resolver casos','nav:cases','secondary')}</div><div class="dashboard"><section><div class="hero"><span class="eyebrow">${state.session?'Tu práctica te espera':'Tu próximo paso'} · módulo ${next.module}</span><h2>${state.session?'Retomá donde lo dejaste':e(next.title)}</h2><p>${state.session?'La sesión quedó guardada en este dispositivo.':e(next.goal)}</p><div class="hero-bottom">${btn(`${state.session?'Continuar práctica':'Empezar lección'} ${icon('right')}`,state.session?'resume':`lesson:${next.id}`)}<span class="small">${icon('clock')} 5–8 min</span></div></div><div class="section-title"><h2>Mi camino</h2><span>${completed} de ${LESSONS.length} lecciones</span></div><div class="module-list">${MODULES.map(m=>`<button class="module ${next.module===m.id?'current':''}" data-action="module:${m.id}" style="--module-bg:${m.color}"><span class="module-number">${percent(m.id)===100?icon('check'):String(m.id).padStart(2,'0')}</span><span class="module-main"><h3>${e(m.title)}</h3><span class="small">${LESSONS.filter(l=>l.module===m.id).length} lecciones · ${e(m.subtitle)}</span><span class="progress-line" role="progressbar" aria-label="Dominio de ${e(m.title)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent(m.id)}"><span style="width:${percent(m.id)}%"></span></span></span>${icon('right')}</button>`).join('')}</div></section><aside class="aside"><section class="panel"><h3>Tu meta de hoy</h3><span class="goal-number">${Math.min(today,10)} <span class="muted" style="font-size:1rem">/ 10 ejercicios</span></span><div class="progress-line"><span style="width:${Math.min(today,10)*10}%"></span></div>${weekly()}<p class="small muted" style="margin-top:15px">${today>=10?'Meta cumplida. Un paso más en tu camino.':'Cinco minutos también cuentan.'}</p></section><section class="panel tip"><h3>${icon('bolt')} Aprender, no adivinar</h3><p>Leé la explicación incluso cuando acertás. Entender por qué es lo que te prepara para un caso nuevo.</p></section><section class="panel"><span class="chip">MODO PARCIAL</span><h3 style="margin-top:15px">Poné todo en juego</h3><p class="small muted">24 ejercicios, mezclados entre los 6 módulos. Corrección al terminar.</p>${btn('Ir al simulacro','nav:exam','secondary stretch','style="margin-top:18px"')}</section></aside></div>`;}
function modulePage(){const m=MODULES.find(m=>m.id===moduleId);return `<div class="narrow"><div class="page-head">${btn(`${icon('left')} Mi camino`,'nav:learn','back')}<div class="chips" style="margin-top:25px"><span class="chip">MÓDULO ${m.id}</span><span class="chip">${percent(m.id)}% dominado</span></div><h1>${e(m.title)}</h1><p class="muted">${e(m.subtitle)}. Elegí una lección; podés recorrerlas en el orden que necesites.</p></div><div class="lesson-list">${LESSONS.filter(l=>l.module===m.id).map((l,i)=>`<article class="lesson-row"><span class="lesson-badge" style="background:${m.color}">${state.lessons[l.id]?.best>=80?'✓':i+1}</span><div class="body"><span class="eyebrow muted">LECCIÓN ${i+1} · 5–8 MIN</span><h3>${e(l.title)}</h3><p class="small muted">${e(l.goal)}</p>${state.lessons[l.id]?`<span class="small">Mejor resultado: ${state.lessons[l.id].best}%</span>`:''}</div>${btn(state.lessons[l.id]?'Repasar':'Aprender',`lesson:${l.id}`)}</article>`).join('')}</div>${btn('Practicar este módulo',`practice:${m.id}`,'secondary stretch')}</div>`;}
function source(l){return `<div class="source">Guía de estudio · pp. ${e(l.pages)}. ${l.refs.map(([key,arts])=>`<a href="${SOURCES[key].url}" target="_blank" rel="noopener noreferrer">${e(SOURCES[key].name)} · ${e(arts)}</a>`).join(' · ')}</div>`;}
function lessonPage(){const l=currentLesson();return `<div class="narrow"><div class="study-title">${btn(`${icon('left')} ${l.module>6?'Biblioteca extra':'Módulo '+l.module}`,l.module>6?'nav:notes':`module:${l.module}`,'back')}${l.module>6?'<p class=notice>Práctica extra posterior al primer parcial.</p>':''}<span class="chip" style="margin-top:25px">PRIMERO, LA IDEA</span><h1>${e(l.title)}</h1><p class="muted">${e(l.goal)}</p></div><article class="study-card reading">${l.paragraphs.map(p=>`<p>${e(p)}</p>`).join('')}<div class="example"><h3>Llevémoslo a un caso</h3><p>${e(l.example)}</p></div><div class="remember"><b>Quedate con esto</b><p>${e(l.remember)}</p></div>${source(l)}</article><div class="study-footer"><span class="small muted">${l.questions.length} ejercicios · sin límite de intentos</span>${btn(`Vamos a practicar ${icon('right')}`,`start:${l.id}`)}</div></div>`;}
function answerText(q,a=correctAnswer(q)){if(q.type==='match')return q.pairs.map(([label],i)=>`${label} → ${q.pairs[a?.[i]]?.[1]||'Sin responder'}`).join(' · ');if(q.type==='order')return (a||[]).map(i=>q.items[i]).join(' → ');if(q.type==='multi')return (a||[]).map(i=>q.options[i]).join(' · ');return q.options[a]||'Sin responder';}
function quizPage(){const s=state.session;if(!s)return learn();const entry=s.questions[s.index],q=byId[entry.id],a=s.answers[s.index],locked=!!a,show=locked&&s.mode!=='exam',l=ALL_LESSONS.find(l=>l.id===q.lesson),labels={choice:q.label||'Elegí una respuesta',multi:'Elegí todas las correctas',match:'Relacioná los conceptos',order:'Ordená los pasos'};return `<div class="narrow question"><div class="quiz-head">${btn('×','exit','close-btn','aria-label="Salir de la práctica"')}<div class="progress-line" role="progressbar" aria-label="Avance de la práctica" aria-valuemin="0" aria-valuemax="${s.questions.length}" aria-valuenow="${s.index+(locked?1:0)}"><span style="width:${(s.index+(locked?1:0))/s.questions.length*100}%"></span></div><span class="question-number">${s.index+1} / ${s.questions.length}</span></div>${s.mode==='exam'?'<div class="exam-banner small">Simulacro · las respuestas se corrigen al finalizar</div>':''}<span class="chip">${e(labels[q.type])}</span><h2 id="question-heading" tabindex="-1">${e(q.prompt)}</h2>${q.scenario?`<p class="scenario">${e(q.scenario)}</p>`:''}<fieldset ${locked?'disabled':''}><legend class="visually-hidden">Tu respuesta</legend>${q.type==='choice'||q.type==='multi'?`<div class="options">${entry.order.map((i,n)=>{const chosen=q.type==='multi'?entry.value.includes(i):entry.value===i;const correct=q.type==='multi'?q.answer.includes(i):q.answer===i;return `<button type="button" class="option ${chosen?'selected':''} ${show&&correct?'correct':''} ${show&&chosen&&!correct?'wrong':''}" data-action="option:${i}" aria-pressed="${chosen}"><span class="option-key">${q.type==='multi'?(chosen?'✓':'+'):n+1}</span><span>${e(q.options[i])}</span></button>`;}).join('')}</div>`:q.type==='match'?`<div>${q.pairs.map(([label],i)=>`<div class="match-row"><label for="match-${i}">${e(label)}</label><select id="match-${i}" data-match="${i}"><option value="-1">Elegí una relación</option>${entry.order.map(j=>`<option value="${j}" ${entry.value[i]===j?'selected':''}>${e(q.pairs[j][1])}</option>`).join('')}</select></div>`).join('')}</div>`:`<p class="small muted" style="margin-bottom:15px">Mové cada paso con las flechas, del primero al último.</p><div class="order-list">${entry.value.map((i,n)=>`<div class="order-item"><b>${n+1}</b><span>${e(q.items[i])}</span><button type="button" data-action="up:${n}" aria-label="Subir ${e(q.items[i])}" ${n===0?'disabled':''}>↑</button><button type="button" data-action="down:${n}" aria-label="Bajar ${e(q.items[i])}" ${n===entry.value.length-1?'disabled':''}>↓</button></div>`).join('')}</div>`}</fieldset>${show?`<section class="feedback ${a.ok?'':'bad'}" role="status"><h3>${a.ok?'Bien pensado.':'Acá hay algo para aprender.'}</h3>${!a.ok?`<p><b>Respuesta:</b> ${e(answerText(q))}</p>`:''}<p>${e(q.explanation)}</p>${source(l)}</section>`:locked?'<p class="feedback" role="status">Respuesta guardada. La verás corregida al terminar.</p>':''}<div class="quiz-footer">${btn(locked?(s.index===s.questions.length-1?'Ver resultado':'Continuar'):'Comprobar',locked?'next':'submit','primary',!locked&&!hasAnswer(q,entry.value)?'disabled':'')}</div></div>`;}
function resultPage(){const s=state.session;if(!s)return learn();const right=s.answers.filter(a=>a.ok).length,pct=Math.round(right/s.questions.length*100),wrong=s.answers.filter(a=>!a.ok);return `<div class="narrow"><div class="result"><div class="result-mark">${pct>=80?'✓':'↗'}</div><span class="eyebrow">${s.mode==='exam'?'SIMULACRO COMPLETADO':'PRÁCTICA COMPLETADA'}</span><h1 style="margin-top:15px">${pct>=80?'Lo estás conectando.':'Cada error te muestra el camino.'}</h1><p class="muted">${pct>=80?'Buen trabajo. Volvé a practicar más adelante para consolidarlo.':'Revisá las explicaciones y volvé a intentarlo, sin perder vidas.'}</p><div class="result-stats"><div class="result-stat"><strong>${right}/${s.questions.length}</strong><span>Respuestas correctas</span></div><div class="result-stat"><strong>${pct}%</strong><span>En esta práctica</span></div><div class="result-stat"><strong>${streakDays(state)}</strong><span>Días de práctica</span></div></div><div class="action-row">${wrong.length?btn('Repasar mis errores','retry-errors'):btn('Seguir mi camino','finish-session')}${wrong.length?btn('Volver al camino','finish-session','secondary'):''}</div></div>${s.mode==='exam'?`<h2>Tu corrección completa</h2>`:wrong.length?'<h2>Para tu próximo intento</h2>':''}${(s.mode==='exam'?s.answers:wrong).map(a=>{const q=byId[a.id];return `<details class="mistake"><summary>${a.ok?'✓':'↗'} ${e(q.prompt)}</summary><p class="small muted">Tu respuesta: ${e(answerText(q,a.value))}</p><p><b>Respuesta esperada:</b> ${e(answerText(q))}</p><p>${e(q.explanation)}</p>${source(ALL_LESSONS.find(l=>l.id===q.lesson))}</details>`;}).join('')}</div>`;}
function reviewPage(){const wrong=mistakeQuestions(state),due=dueQuestions(state);return `<div class="narrow"><div class="page-head"><span class="eyebrow">HACER QUE QUEDE</span><h1>Volver es avanzar.</h1><p class="muted">Reforzá lo que costó y recuperá lo aprendido. Los aciertos vuelven a los 1, 3, 7 y 14 días de práctica espaciada.</p></div><div class="two-col"><section class="panel"><span class="goal-number">${wrong.length}</span><h3>Errores para trabajar</h3><p class="small muted">Cada uno guarda una explicación y su tema.</p>${btn('Practicar errores','review-errors','primary stretch',`style="margin-top:18px" ${wrong.length?'':'disabled'}`)}</section><section class="panel"><span class="goal-number">${due.length}</span><h3>Repasos pendientes</h3><p class="small muted">Preguntas ya vistas que toca recuperar.</p>${btn('Hacer un repaso','review-due','secondary stretch',`style="margin-top:18px" ${due.length?'':'disabled'}`)}</section></div>${wrong.length?`<h2>Lo que vamos a reforzar</h2><div class="review-list" style="margin-top:18px">${MODULES.filter(m=>wrong.some(q=>LESSONS.find(l=>l.id===q.lesson).module===m.id)).map(m=>`<button class="module" data-action="module:${m.id}"><span class="module-number" style="--module-bg:${m.color}">${icon(m.icon)}</span><span class="module-main"><h3>${e(m.title)}</h3><span class="small">${wrong.filter(q=>LESSONS.find(l=>l.id===q.lesson).module===m.id).length} ejercicios para reforzar</span></span>${icon('right')}</button>`).join('')}</div>`:`<div class="empty"><h2>Sin errores pendientes</h2><p class="muted">${QUESTIONS.some(q=>state.cards[q.id])?'Podés seguir con otro tema o probar un repaso mixto.':'Empezá una lección para construir tu repaso personal.'}</p>${btn('Repaso mixto de 10 preguntas','practice-all')}</div>`}<section class="panel" style="margin-top:20px"><h3>¿Listo para integrar?</h3><p class="muted">Practicá los seis módulos con un simulacro de 24 ejercicios.</p>${btn('Preparar simulacro','nav:exam','secondary','style="margin-top:15px"')}</section></div>`;}
function examPage(){return `<div class="narrow"><div class="page-head"><span class="chip">MODO PARCIAL</span><h1>Probá el panorama completo.</h1><p class="muted">24 ejercicios seleccionados al azar del banco de práctica: 4 por módulo, sin reloj y con corrección al terminar.</p></div><section class="study-card"><h2>Un ensayo para conectar temas</h2><div class="reading"><p>Podés encontrar casos, asociaciones, secuencias y preguntas de selección. Una vez confirmada una respuesta, avanzás sin modificarla.</p><p>Al finalizar vas a ver tu resultado, la respuesta esperada y la explicación de cada ejercicio. El porcentaje es orientativo: no reproduce la nota ni las consignas de tu docente.</p></div><div class="notice">${e(SCOPE.text)} <button class="inline-link" data-action="nav:sources">Ver alcance detallado</button></div>${btn('Empezar simulacro','start-exam','primary stretch')}</section></div>`;}
function notesPage(){const l=LESSONS[flashIndex];return `<div class="narrow"><div class="page-head"><span class="eyebrow">IDEAS PARA LLEVAR</span><h1>Tu biblioteca de bolsillo.</h1><p class="muted">Intentá recordar la idea antes de dar vuelta la tarjeta. Esto no suma XP: es un espacio para recuperar conceptos.</p></div><button class="study-card flash stretch" data-action="flip" aria-label="${flashBack?'Ver pregunta':'Mostrar idea clave'}"><span class="eyebrow">${flashBack?'LA IDEA CLAVE':`TARJETA ${flashIndex+1} DE ${LESSONS.length}`}</span><h2>${e(l.title)}</h2><p>${e(flashBack?l.remember:l.goal)}</p><span class="small muted" style="margin-top:22px">Tocá para ${flashBack?'volver':'dar vuelta'}</span></button><div class="study-footer">${btn(`${icon('left')} Anterior`,'flash-prev','secondary')}${btn('Ver lección',`lesson:${l.id}`,'ghost')}${btn(`Siguiente ${icon('right')}`,'flash-next','secondary')}</div><div class="section-title"><h2>Todos los temas</h2></div><div class="lesson-list">${MODULES.map(m=>`<details class="panel"><summary><b>${e(m.title)}</b></summary>${LESSONS.filter(l=>l.module===m.id).map(l=>`<p style="margin-top:12px"><button class="inline-link" data-action="lesson:${l.id}">${e(l.title)}</button></p>`).join('')}</details>`).join('')}</div><section class="panel"><h2>Extra · después del primer parcial</h2><p class="muted">Estas lecciones se conservan como consulta. No entran en el recorrido ni en el simulacro del 18/09.</p>${EXTRA_LESSONS.map(x=>`<p>${btn(e(x.title),`lesson:${x.id}`,'ghost')}</p>`).join('')}</section></div>`;}
function progressPage(){const done=completion(state),pct=Math.round(done/LESSONS.length*100);return `<div class="narrow"><div class="page-head"><span class="eyebrow">PASO A PASO</span><h1>Tu avance es tuyo.</h1><p class="muted">Se guarda en este navegador, incluso si cerrás la app. No se sincroniza automáticamente entre dispositivos.</p></div><div class="two-col"><section class="panel" style="text-align:center"><h3>Lecciones dominadas</h3><div class="total-ring" style="--progress:${pct}%"><span>${pct}%</span></div><p>${done} de ${LESSONS.length} lecciones</p><p class="small muted">Dominio: mejor intento de al menos 80%.</p></section><section class="panel"><h3>Tu constancia</h3><p><span class="goal-number">${streakDays(state)}</span> ${streakDays(state)===1?'día seguido':'días seguidos'}</p>${weekly()}<p style="margin-top:20px"><b>${state.xp} XP</b> acumulados</p><p class="small muted">10 XP por pregunta acertada, una vez por día. Practicar más no te penaliza.</p></section></div><section class="panel"><h3>Llevá el progreso a tu celular</h3><p class="muted">Exportá una copia e importala en el otro dispositivo. Importar reemplaza el progreso de ese navegador.</p><div class="action-row" style="justify-content:start;margin-top:20px">${btn('Exportar progreso','export','secondary')}${btn('Importar copia','import','secondary')}<input type="file" id="import-file" accept="application/json,.json" hidden></div></section><section class="panel" style="margin-top:20px"><h3>Usar como app</h3><p class="muted">Una vez publicada en GitHub Pages, abrila en el navegador del celular y elegí «Agregar a pantalla de inicio». Después de la primera carga, el contenido queda disponible sin conexión.</p><p class="small muted" style="margin-top:12px" id="offline-status">${navigator.serviceWorker?.controller?'Contenido disponible sin conexión en este dispositivo.':'La disponibilidad sin conexión se prepara al abrir desde HTTPS o localhost.'}</p></section><p style="margin-top:20px">${btn('Alcance y fuentes','nav:sources','ghost')}${btn('Reiniciar progreso','reset','ghost')}</p></div>`;}
function sourcesPage(){return `<div class="narrow sources-list"><div class="page-head"><span class="eyebrow">QUÉ ESTÁS ESTUDIANDO</span><h1>Alcance y fuentes.</h1></div><section class="study-card"><h2>Hasta el primer parcial</h2><p>${e(SCOPE.text)} El cronograma local fija el parcial el 18/09/2026.</p><div class="notice">${e(SCOPE.note)}</div><p>El recorrido incluye compraventa, permuta, cesión, fondo de comercio, nociones de venta internacional, locación, leasing, comodato, mandato, representación, consignación, gestión de negocios, empleo útil y donación.</p><h3>Base de estudio</h3><p>Guía: ${e(SCOPE.guide)} y cronograma de comisión: ${e(SCOPE.schedule)}. El cronograma de Prieto determina el alcance; las páginas de la guía son referencias complementarias. Las actividades generales están redactadas para esta app. Casos incluye los 130 casos de los seis Word con sus 410 consignas originales. La práctica extra conserva los casos de los PPT y la actividad de pagaré, con referencia por ficha; no son preguntas oficiales del examen. Las grabaciones no fueron transcritas ni usadas para afirmar qué dijo la docente.</p><h3>Normas de referencia</h3>${Object.values(SOURCES).map(s=>`<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${e(s.name)}</a></p>`).join('')}<p class="small muted">Consulta normativa: ${SCOPE.date}. Las referencias particulares aparecen en cada lección y explicación. La app es material de estudio, no asesoramiento para un caso real.</p><h3>Precisiones importantes</h3><p>La mora automática se referencia al art. 886; el 888 trata la eximición. Se distingue papel de modalidades no cartulares, fianza de principal pagador y prenda común de prenda con registro. En locación se evita memorizar un plazo mínimo universal anterior a las reformas.</p><h3>Tu información</h3><p>El progreso se almacena localmente. No hay cuenta, publicidad, seguimiento ni servidor de datos. El proyecto no incluye grabaciones, archivos Word/PPT ni conversaciones personales. Sí contiene el texto de los enunciados y consignas incorporados para estudiar.</p></section></div>`;}
function render({focus=false}={}){document.body.classList.toggle('quiz-mode',view==='quiz');const pages={learn,cases:caseUI.list,case:caseUI.detail,module:modulePage,lesson:lessonPage,quiz:quizPage,result:resultPage,review:reviewPage,notes:notesPage,progress:progressPage,exam:examPage,sources:sourcesPage};root.innerHTML=shell((pages[view]||learn)());if(focus){window.scrollTo({top:0});const heading=document.querySelector(view==='quiz'?'#question-heading':'h1');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}}}
function go(next){view=next;render({focus:true});}
function start(mode,questions,lid=null){if(!questions.length){toast('Todavía no hay preguntas para este repaso.');return;}if(state.session&&!state.session.finished){toast('Tenés una sesión guardada. Podés retomarla o descartarla desde la práctica.');go('quiz');return;}state.session=makeSession(mode,questions,lid);state.lastLesson=lid||state.lastLesson;save();go('quiz');}
function askChange(title,description,change){pendingChange=change;document.querySelector('#change-title').textContent=title;document.querySelector('#change-description').textContent=description;document.querySelector('#confirm-change').showModal();}
function action(raw){if(caseUI.action(raw))return;const [a,id]=raw.split(':');if(a==='nav'){go(id);return;}if(a==='module'){moduleId=Number(id);go('module');return;}if(a==='lesson'){lessonId=id;go('lesson');return;}if(a==='start'){const l=ALL_LESSONS.find(l=>l.id===id);if(l)start('lesson',l.questions,l.id);return;}if(a==='practice'){start('practice',shuffle(QUESTIONS.filter(q=>LESSONS.find(l=>l.id===q.lesson).module===Number(id))).slice(0,10));return;}
 if(a==='resume'){go(state.session?.finished?'result':'quiz');return;}if(a==='practice-all'){start('practice',shuffle(QUESTIONS).slice(0,10));return;}if(a==='start-exam'){start('exam',examQuestions());return;}if(a==='review-errors'){start('review',shuffle(mistakeQuestions(state)).slice(0,12));return;}if(a==='review-due'){start('review',dueQuestions(state).slice(0,12));return;}
 if(a==='exit'){document.querySelector('#confirm-exit').showModal();return;}if(a==='cancel-exit'){document.querySelector('#confirm-exit').close();return;}if(a==='save-exit'){save();go('learn');return;}if(a==='discard'||a==='finish-session'){state.session=null;save();go('learn');return;}
 if(a==='retry-errors'){const qs=state.session.answers.filter(x=>!x.ok).map(x=>byId[x.id]);state.session=null;start('review',shuffle(qs));return;}
 if(a==='flip'){flashBack=!flashBack;render();return;}if(a==='flash-prev'||a==='flash-next'){flashIndex=(flashIndex+(a==='flash-next'?1:-1)+LESSONS.length)%LESSONS.length;flashBack=false;render();return;}
 if(a==='reset'){askChange('Reiniciar progreso','Se eliminará el progreso de este navegador. Exportá una copia antes si querés conservarlo.',{type:'reset'});return;}if(a==='cancel-change'){pendingChange=null;document.querySelector('#confirm-change').close();return;}if(a==='apply-change'){if(!pendingChange)return;const importing=pendingChange.type==='import';state=importing?pendingChange.state:freshState();pendingChange=null;save();go(importing?'progress':'learn');toast(importing?'Progreso importado.':'Progreso reiniciado.');return;}if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`obliga-progreso-${dayKey()}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),5000);return;}if(a==='import'){document.querySelector('#import-file').click();return;}
 const s=state.session;if(!s||s.finished)return;const entry=s.questions[s.index],q=byId[entry.id];if(a==='next'){advance(state);save();go(s.finished?'result':'quiz');return;}if(s.feedback)return;
 if(a==='option'){const val=Number(id);if(q.type==='multi')entry.value=entry.value.includes(val)?entry.value.filter(x=>x!==val):[...entry.value,val];else entry.value=val;save();render();return;}
 if(a==='up'||a==='down'){const i=Number(id),j=i+(a==='up'?-1:1);if(j>=0&&j<entry.value.length)[entry.value[i],entry.value[j]]=[entry.value[j],entry.value[i]];save();render();return;}
 if(a==='submit'){if(submitAnswer(state,entry.value)){save();render();document.querySelector('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});}return;}
}
root.addEventListener('click',ev=>{const target=ev.target.closest('[data-action]');if(target&&!target.disabled)action(target.dataset.action);});
root.addEventListener('input',caseUI.input);
root.addEventListener('change',async ev=>{if(ev.target.matches('[data-match]')){const s=state.session;if(!s||s.feedback)return;s.questions[s.index].value[Number(ev.target.dataset.match)]=Number(ev.target.value);save();const q=byId[s.questions[s.index].id];document.querySelector('[data-action="submit"]').disabled=!hasAnswer(q,s.questions[s.index].value);}if(ev.target.id==='import-file'){const file=ev.target.files[0];if(!file)return;try{if(file.size>10000000)throw new Error('La copia es demasiado grande.');const incoming=validateState(JSON.parse(await file.text()));askChange('Importar progreso','La copia reemplazará el progreso de este navegador.',{type:'import',state:incoming});}catch(err){toast(err.message||'No se pudo leer la copia.');}}});
document.addEventListener('keydown',ev=>{if(view!=='quiz'||document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName))return;const s=state.session,q=s&&byId[s.questions[s.index].id];if(!q)return;if(/^[1-9]$/.test(ev.key)&&['choice','multi'].includes(q.type)&&!s.feedback){const index=s.questions[s.index].order[Number(ev.key)-1];if(index!==undefined)action(`option:${index}`);}if(ev.key==='Enter'){ev.preventDefault();action(s.feedback?'next':'submit');}});
if('serviceWorker'in navigator&&(location.protocol==='https:'||['localhost','127.0.0.1'].includes(location.hostname)))navigator.serviceWorker.register('./sw.js', {updateViaCache:'none'}).then(()=>navigator.serviceWorker.ready).then(()=>{const s=document.querySelector('#offline-status');if(s)s.textContent='Contenido preparado para usar sin conexión.';}).catch(()=>{});
try{const ctx=document.modelContext;if(ctx?.registerTool){const signal=new AbortController();for(const tool of [{name:'obliga_read_progress',title:'Leer avance de estudio',description:'Lee el progreso local de Obliga sin modificarlo.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({xp:state.xp,mastered:completion(state),total:LESSONS.length,errors:mistakeQuestions(state).length})},{name:'obliga_open_lesson',title:'Abrir una lección',description:'Navega a una explicación. No responde preguntas ni marca lecciones como completadas.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!LESSONS.some(l=>l.id===input.lessonId))throw new Error('Lección inexistente');lessonId=input.lessonId;go('lesson');return {opened:lessonId};}}])Promise.resolve(ctx.registerTool(tool,{signal:signal.signal})).catch(()=>{});window.addEventListener('pagehide',()=>signal.abort(),{once:true});}}catch{}
render();
